/**
 * Copy a Character Forge dist into public/vendor/character-forge/<version>/.
 * The vendored tree is generated by this script. Do not hand-edit it.
 *
 * Usage:
 *   node tools/sync-character-bundle.mjs <CF_DIST>
 *   CF_DIST=/path/to/dist/1.2.0 node tools/sync-character-bundle.mjs
 *
 * CF_DIST is the directory that contains bundle.json and cf-runtime.mjs
 * (the unpacked dist/<version>/ folder, not the tarball root).
 */
import {
  cpSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
export const VENDOR_ROOT = join(root, 'public', 'vendor', 'character-forge');
export const DEFAULT_MAX_BYTES = 10 * 1024 * 1024;

/**
 * @param {string} dist
 * @param {{ destRoot?: string, maxBytes?: number }} [options]
 * @returns {{ version: string, generatorVersion: number, dest: string, files: number }}
 */
export function syncCharacterBundle(dist, options = {}) {
  const source = resolve(dist);
  const destRoot = options.destRoot ?? VENDOR_ROOT;
  const maxBytes = options.maxBytes ?? DEFAULT_MAX_BYTES;
  const bundlePath = join(source, 'bundle.json');
  const runtimePath = join(source, 'cf-runtime.mjs');
  const bundle = JSON.parse(readFileSync(bundlePath, 'utf8'));
  const version = bundle?.engine?.version;
  const generatorVersion = bundle?.generator?.version;
  if (typeof version !== 'string' || !/^\d+\.\d+\.\d+$/.test(version)) {
    throw new Error('CF bundle is missing engine.version (expected 1.2.3)');
  }
  if (typeof generatorVersion !== 'number' || !Number.isInteger(generatorVersion)) {
    throw new Error('CF bundle is missing generator.version');
  }
  if (!statSync(runtimePath).isFile()) {
    throw new Error('CF dist is missing cf-runtime.mjs');
  }

  const dest = join(destRoot, version);
  rmSync(dest, { recursive: true, force: true });
  mkdirSync(dest, { recursive: true });
  cpSync(source, dest, { recursive: true, dereference: true });

  const tooBig = [];
  let files = 0;
  walk(dest, (file, size) => {
    files += 1;
    if (size > maxBytes) tooBig.push(`${relative(destRoot, file)} is ${size} bytes`);
  });
  if (tooBig.length > 0) {
    rmSync(dest, { recursive: true, force: true });
    throw new Error(`Refusing to vendor files over ${maxBytes} bytes:\n${tooBig.join('\n')}`);
  }

  const pin = { version, generatorVersion };
  writeFileSync(join(destRoot, 'current.json'), `${JSON.stringify(pin, null, 2)}\n`);
  return { version, generatorVersion, dest, files };
}

/**
 * @param {string} dir
 * @param {(file: string, size: number) => void} visit
 */
function walk(dir, visit) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      walk(full, visit);
      continue;
    }
    if (!entry.isFile()) continue;
    visit(full, statSync(full).size);
  }
}

const invoked = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (invoked) {
  const dist = process.argv[2] || process.env.CF_DIST;
  if (!dist) {
    console.error('Usage: node tools/sync-character-bundle.mjs <CF_DIST>');
    console.error('CF_DIST may also be set in the environment.');
    process.exit(1);
  }
  try {
    const result = syncCharacterBundle(dist);
    console.log(
      `vendored Character Forge ${result.version} (generator ${result.generatorVersion}) → ${relative(root, result.dest)} (${result.files} files)`,
    );
  } catch (error) {
    console.error(error instanceof Error ? error.message : error);
    process.exit(1);
  }
}
